// ── Prime Radiant, the "living wiki": every string, in all ten locales ──
//
// One module for the surface, merged into the catalogue by translations.ts
// (the Screenshot app's shape). Each locale is typed against the English keys:
// a key missing from one language is a compile error before it is a test
// failure. "Prime Radiant", "Memory Shard", "ClawBox AI", "Flash" and "Opus"
// are product and model names and stay as they are in every language.

